INSERT INTO public.jobs (title, company, location, province, type, salary_min, salary_max, currency, sector, description, requirements, is_active) VALUES ('Data Analyst', 'Jozi Analytics', 'Sandton, Johannesburg', 'Gauteng', 'Full-time', 384000, 456000, 'ZAR', 'IT & Tech', 'Turn operational data into dashboards and insights for retail and logistics clients. Build reports, clean datasets, and present findings to non-technical teams.', ARRAY['3+ years in data analysis or business intelligence', 'Strong SQL and Excel skills, Power BI or Tableau experience', 'Understanding of data cleaning and validation', 'Clear written and verbal communication skills'], true);
INSERT INTO public.jobs (title, company, location, province, type, salary_min, salary_max, currency, sector, description, requirements, is_active) VALUES ('Millwright', 'Limpopo Industrial Services', 'Polokwane', 'Limpopo', 'Full-time', 324000, 396000, 'ZAR', 'Manufacturing', 'Install, maintain and repair industrial machinery at food processing and packaging plants around Polokwane. Respond to breakdowns and run planned maintenance.', ARRAY['Qualified millwright trade test (red seal preferred)', '3+ years plant maintenance experience', 'Knowledge of hydraulics, pneumatics and PLC basics', 'Willingness to work standby shifts when required'], true);
INSERT INTO public.jobs (title, company, location, province, type, salary_min, salary_max, currency, sector, description, requirements, is_active) VALUES ('Registered Nurse (ICU)', 'Lowveld Care Hospital', 'Mbombela', 'Mpumalanga', 'Full-time', 348000, 420000, 'ZAR', 'Healthcare', 'Provide critical care nursing in a busy private hospital ICU. Monitor ventilated patients, administer treatment, and support families through recovery.', ARRAY['Registered with the South African Nursing Council', 'Post-basic qualification in critical care nursing', '3+ years hospital nursing experience, ICU preferred', 'Calm under pressure with strong clinical judgement'], true);
INSERT INTO public.jobs (title, company, location, province, type, salary_min, salary_max, currency, sector, description, requirements, is_active) VALUES ('Solar Installation Electrician', 'Kalahari Solar Projects', 'Upington', 'Northern Cape', 'Contract', 240000, 288000, 'ZAR', 'Construction & Engineering', 'Install rooftop and ground-mount solar systems for homes, farms and businesses across the Northern Cape. Work with a senior installer on wiring, inverters and commissioning.', ARRAY['Electrical trade qualification or N3 with practical experience', 'Understanding of solar PV basics and SANS wiring codes', 'Comfortable working at heights and outdoors', 'Valid driver''s licence and willingness to travel'], true);
INSERT INTO public.jobs (title, company, location, province, type, salary_min, salary_max, currency, sector, description, requirements, is_active) VALUES ('Junior Accountant', 'Coastal Ledger Partners', 'Umhlanga', 'KwaZulu-Natal', 'Full-time', 288000, 336000, 'ZAR', 'Finance & Banking', 'Support a Durban accounting practice with bookkeeping, VAT returns and month-end packs for small business clients. Grow towards a SAIPA or SAICA articles path.', ARRAY['BCom Accounting or equivalent degree', 'Working knowledge of Pastel, Xero or Sage', 'Strong Excel and attention to detail', 'Good client communication skills'], true);
INSERT INTO public.jobs (title, company, location, province, type, salary_min, salary_max, currency, sector, description, requirements, is_active) VALUES ('Farm Manager (Citrus)', 'Mopani Citrus Estates', 'Letsitele', 'Limpopo', 'Full-time', 420000, 492000, 'ZAR', 'Agriculture', 'Manage a 400-hectare citrus estate near Letsitele, from irrigation and pest control to harvest planning and packhouse coordination for export markets.', ARRAY['5+ years citrus or subtropical fruit farm management', 'Degree or diploma in Agriculture or Horticulture', 'Experience with irrigation scheduling and export standards', 'Strong team leadership and budgeting skills'], true);
INSERT INTO public.jobs (title, company, location, province, type, salary_min, salary_max, currency, sector, description, requirements, is_active) VALUES ('Exploration Geologist', 'Bushveld Mineral Exploration', 'Klerksdorp', 'North West', 'Contract', 600000, 720000, 'ZAR', 'Mining & Resources', 'Lead field mapping and drilling programmes for gold and platinum exploration in the Bushveld Complex. Log core, build geological models and report to the project team.', ARRAY['BSc Honours in Geology or Earth Sciences', '3+ years exploration or mine geology experience', 'Core logging and geological modelling skills', 'Willingness to work on remote field sites'], true);
INSERT INTO public.jobs (title, company, location, province, type, salary_min, salary_max, currency, sector, description, requirements, is_active) VALUES ('High School Mathematics Teacher', 'Eastern Cape Learning Trust', 'Mthatha', 'Eastern Cape', 'Full-time', 324000, 396000, 'ZAR', 'Education', 'Teach Grade 10–12 Mathematics at a Mthatha high school, run extra lessons for matric learners, and help raise pass rates in a district with a maths teacher shortage.', ARRAY['BEd or PGCE with Mathematics as a major', 'Registered with SACE', '3+ years teaching FET Mathematics', 'Commitment to extra lessons and learner support'], true);
INSERT INTO public.jobs (title, company, location, province, type, salary_min, salary_max, currency, sector, description, requirements, is_active) VALUES ('Warehouse Supervisor', 'Boland Distribution Co', 'Parow, Cape Town', 'Western Cape', 'Full-time', 312000, 360000, 'ZAR', 'Retail & FMCG', 'Run daily warehouse operations for a fast-moving consumer goods distributor. Manage picking, packing and dispatch teams and keep stock accuracy above target.', ARRAY['3+ years warehouse or logistics supervision', 'Experience with warehouse management systems', 'Forklift licence an advantage', 'Strong planning and people management skills'], true);
INSERT INTO public.jobs (title, company, location, province, type, salary_min, salary_max, currency, sector, description, requirements, is_active) VALUES ('Cybersecurity Analyst', 'Sentinel Cyber SA', 'Midrand', 'Gauteng', 'Full-time', 576000, 672000, 'ZAR', 'IT & Tech', 'Monitor client networks for threats, triage security alerts, and help run incident response for South African financial and retail clients.', ARRAY['3+ years in IT security, SOC or network operations', 'Familiarity with SIEM tools and incident response', 'Security+ or equivalent certification preferred', 'Strong analytical and report-writing skills'], true);
INSERT INTO public.jobs (title, company, location, province, type, salary_min, salary_max, currency, sector, description, requirements, is_active) VALUES ('Community Development Officer', 'Free State Development Agency', 'Bloemfontein', 'Free State', 'Contract', 264000, 312000, 'ZAR', 'Government & Public Sector', 'Support community upliftment projects in Bloemfontein townships: run needs assessments, coordinate local SMME support, and report on programme outcomes.', ARRAY['Diploma or degree in Development Studies or Social Sciences', 'Experience working with community groups', 'Strong facilitation and report-writing skills', 'Valid driver''s licence for site visits'], true);
INSERT INTO public.jobs (title, company, location, province, type, salary_min, salary_max, currency, sector, description, requirements, is_active) VALUES ('Diesel Mechanic', 'Highveld Fleet Services', 'Middelburg', 'Mpumalanga', 'Full-time', 372000, 444000, 'ZAR', 'Mining & Resources', 'Service and repair diesel trucks and yellow machinery for mining and logistics clients around Middelburg. Diagnose faults and keep fleet downtime low.', ARRAY['Qualified diesel mechanic trade test', '4+ years servicing trucks or earthmoving equipment', 'Diagnostic and fault-finding experience', 'Own tools an advantage'], true);
